.header {
    gap: 3rem;
    margin: 3rem auto 5rem auto;
    width: 90%;
    max-width: 75rem;
    color: #ddd6cb;
    font-size: 1.5rem;
}

.header h1 {
    font-family: 'Montserrat', sans-serif;
}

.header p {
    margin: 0;
}

